/* Signature Bulgarian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ivanomir": "From Ivan + mir (peace/world): 'peace of Ivan'.", "Marlena": "From Maria + Elena.", "Georgimir": "From Georgi + mir.", "Nadezhdara": "From nadezhda (hope) + dara (gift): 'gift of hope'.", "Dimislava": "From Dimitar + slava (glory).", "Elenomir": "From Elena + mir.", "Ivanomirov": "Signature surname in -ov style built on Ivanomir.", "Nadezhdarov": "Signature surname in -ov style built on Nadezhdara.", "Georgimirov": "Signature surname in -ev style.", "Marlenov": "Signature surname in -ov style built on Marlena."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ivanomir';
console.log(lookup(q));

